class Solution {
  public void gameOfLife(int[][] board) {
    int n = board.length, m = board[0].length;
    // bit 0: current state, bit 1: next state
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        int live = 0;
        for (int di = -1; di <= 1; di++)
          for (int dj = -1; dj <= 1; dj++) {
            if (di == 0 && dj == 0) continue;
            int x = i + di, y = j + dj;
            if (x >= 0 && x < n && y >= 0 && y < m) live += board[x][y] & 1;
          }
        if (live == 3 || (live == 2 && (board[i][j] & 1) == 1)) board[i][j] |= 2;
      }
    }
    for (int[] row : board) for (int j = 0; j < m; j++) row[j] >>= 1;
  }
}
